  const LEVEL_ORDER=["крайне низкий","очень низкий","низкий","средний","высокий","очень высокий","псевдовысокий"];
  function levelName(value){const raw=String(value??"").trim().toLowerCase(),map={very_low:"очень низкий",extremely_low:"крайне низкий",low:"низкий",medium:"средний",high:"высокий",very_high:"очень высокий","псевдовысокий":"псевдовысокий"};return map[raw]||String(value??"").trim();}
  function levelTone(value){const v=levelName(value);if(v.includes("крайне")||v.includes("очень низ"))return "level-very-low";if(v.includes("низ"))return "level-low";if(v.includes("сред"))return "level-medium";if(v.includes("псевдо")||v.includes("очень высок"))return "level-high";if(v.includes("выс"))return "level-high";return "level-medium";}
