    show("method-progress-panel",true);
    const d=methodProgressData||{registered:0,completed_any:0,completed_all:0,rows:[]},registered=Number(d.registered)||0,any=Number(d.completed_any)||0,all=Number(d.completed_all)||0,inProcess=Math.max(0,any-all),list=$("method-progress-list");
