  function renderProgress(){$("progress-stage-note").textContent=reminderStageOpen()?"Этап открыт для выбранной группы.":"Этап ещё не открыт для выбранной группы. Сначала откройте его выше; напоминания пока недоступны.";const rows=selectedProgress(),counts=$("progress-counts");counts.replaceChildren();for(const [name,n]of [["Зарегистрировались",rows.length],["Не начали",rows.filter(p=>p.status==="not_started").length],["Проходят",rows.filter(p=>p.status==="in_progress").length],["Завершили",rows.filter(p=>p.status==="completed").length]]){const cell=document.createElement("div");cell.className="measure";cell.textContent=name;const value=document.createElement("strong");value.textContent=n;cell.append(value);counts.append(cell);}$("progress-people").replaceChildren();for(const p of rows)row($("progress-people"),p.email,({not_started:"Не начал(а)",in_progress:"Проходит",completed:"Завершил(а)"})[p.status]);show("reminder-preview",false);reminderRequest="";}
